import { readFileSync } from "node:fs";
import { describe, expect, test } from "vitest";
import { noseImpulseCushion } from "../../src/index";

/**
 * External reference check for the cushion model (SPEC 5.8, "compare against pooltool").
 *
 * `fixtures/pooltool-cushion.json` holds results computed by pooltool (Evan Kiefl and
 * contributors, Apache-2.0, https://github.com/ekiefl/pooltool) for a grid of cushion impacts,
 * generated by `scripts/pooltool_cushion_reference.py`. Only numbers are stored.
 *
 *  - `han`: pooltool's implementation of Han (2005). Baize's model was derived independently
 *    from the same assumptions and must agree with it to rounding error.
 *  - `mathavan`: pooltool's implementation of Mathavan, Jackson & Parkin (2010), a more
 *    detailed model that integrates through the impact and includes the table's friction.
 *    Baize's v1 model is not expected to match it; the test pins how far apart they are so
 *    the gap is known and cannot grow unnoticed.
 */

interface Fixture {
  source: string;
  balls: { name: string; radiusM: number; massKg: number }[];
  cushions: { noseHeightPerDiameter: number; restitution: number; friction: number }[];
  rows: number[][];
}

const fixture = JSON.parse(
  readFileSync(new URL("../fixtures/pooltool-cushion.json", import.meta.url), "utf8"),
) as Fixture;

interface Impact {
  radiusM: number;
  speed: number;
  angleDeg: number;
  roll: number;
  side: number;
  ours: { vx: number; vy: number; wx: number; wy: number; wz: number };
  han: number[];
  mathavan: number[];
}

const impacts: Impact[] = fixture.rows.map((row) => {
  const [
    bi = 0,
    ci = 0,
    speed = 0,
    angleDeg = 0,
    roll = 0,
    side = 0,
    vx = 0,
    vy = 0,
    wx = 0,
    wy = 0,
    wz = 0,
  ] = row;
  const ball = fixture.balls[bi];
  const cushion = fixture.cushions[ci];
  if (!ball || !cushion) throw new Error("bad fixture row");
  const out = noseImpulseCushion.resolve(
    {
      radiusM: ball.radiusM,
      massKg: ball.massKg,
      velocity: { x: vx, y: vy },
      spin: { x: wx, y: wy, z: wz },
    },
    { x: 1, y: 0 },
    {
      noseHeightM: cushion.noseHeightPerDiameter * 2 * ball.radiusM,
      restitution: cushion.restitution,
      friction: cushion.friction,
    },
  );
  return {
    radiusM: ball.radiusM,
    speed,
    angleDeg,
    roll,
    side,
    ours: {
      vx: out.velocity.x,
      vy: out.velocity.y,
      wx: out.spin.x,
      wy: out.spin.y,
      wz: out.spin.z,
    },
    han: row.slice(11, 16),
    mathavan: row.slice(16, 21),
  };
});

function quantile(values: number[], p: number): number {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.min(sorted.length - 1, Math.floor(p * sorted.length))] as number;
}

describe("cushion model against pooltool", () => {
  test("the fixture is the expected size and comes from pooltool", () => {
    expect(fixture.source).toMatch(/^pooltool \d/);
    expect(impacts.length).toBe(1080);
  });

  test("agrees with pooltool's Han 2005 model to rounding error on every impact", () => {
    for (const i of impacts) {
      const [vx = 0, vy = 0, wx = 0, wy = 0, wz = 0] = i.han;
      const scale = i.speed;
      expect(Math.abs(i.ours.vx - vx) / scale).toBeLessThan(1e-12);
      expect(Math.abs(i.ours.vy - vy) / scale).toBeLessThan(1e-12);
      expect((Math.abs(i.ours.wx - wx) * i.radiusM) / scale).toBeLessThan(1e-12);
      expect((Math.abs(i.ours.wy - wy) * i.radiusM) / scale).toBeLessThan(1e-12);
      expect((Math.abs(i.ours.wz - wz) * i.radiusM) / scale).toBeLessThan(1e-12);
    }
  });

  test("distance from pooltool's Mathavan 2010 model stays within the measured bounds", () => {
    const speedError: number[] = [];
    const angleError: number[] = [];
    for (const i of impacts) {
      const [mx = 0, my = 0] = i.mathavan;
      const ours = Math.hypot(i.ours.vx, i.ours.vy);
      const theirs = Math.hypot(mx, my);
      speedError.push(Math.abs(ours - theirs) / i.speed);
      angleError.push(
        (Math.abs(Math.atan2(i.ours.vy, i.ours.vx) - Math.atan2(my, mx)) * 180) / Math.PI,
      );
      // Both models send the ball back onto the table.
      expect(i.ours.vx).toBeGreaterThan(0);
      expect(mx).toBeGreaterThan(0);
    }
    // Measured on 2026-11-12 (see docs/ARCHITECTURE.md, decisions log): rebound speed differs
    // by a median of about 3 % of the incoming speed and the rebound direction by a median of
    // about 3 degrees; the worst cases are steep impacts with heavy check side or backspin.
    expect(quantile(speedError, 0.5)).toBeLessThan(0.04);
    expect(quantile(speedError, 0.9)).toBeLessThan(0.13);
    expect(quantile(angleError, 0.5)).toBeLessThan(4.5);
    expect(quantile(angleError, 0.9)).toBeLessThan(11);
    expect(quantile(angleError, 1)).toBeLessThan(25);
  });

  test("a plain rolling ball with no side is close to Mathavan at every angle", () => {
    const plain = impacts.filter((i) => i.roll === 1 && i.side === 0);
    expect(plain.length).toBeGreaterThan(50);
    const angle = plain.map((i) => {
      const [mx = 0, my = 0] = i.mathavan;
      return (Math.abs(Math.atan2(i.ours.vy, i.ours.vx) - Math.atan2(my, mx)) * 180) / Math.PI;
    });
    const speed = plain.map((i) => {
      const [mx = 0, my = 0] = i.mathavan;
      return Math.abs(Math.hypot(i.ours.vx, i.ours.vy) - Math.hypot(mx, my)) / i.speed;
    });
    expect(quantile(angle, 0.5)).toBeLessThan(3.5);
    expect(quantile(speed, 0.5)).toBeLessThan(0.04);
  });
});
